        self.state = {'records': {phased.key('design-brief', 'CHR-001'):
                      {'path': 'brief.json', 'sha256': cp.digest(brief)}}}

    def test_state_can_activate_base_not_needed_specialists(self):
        phased.validate_execution(cp, self.root, self.data, self.state, strict=False)

    def test_activation_requires_explicit_state_reason(self):
        del self.data['specialist_execution']['character-face-signature-design']['state_activation_reason']
        with self.assertRaisesRegex(ValueError, 'state_activation_reason'):
            phased.validate_execution(cp, self.root, self.data, self.state, strict=False)


if __name__ == '__main__':
    unittest.main()

files.scripts/prompt_fidelity.py:
"""Source-bound prompt editing checks; this is not a model of visual semantics.

The controller must actually review meaning.  Code checks the complete source
inventory, real text spans, version binding and unambiguous numeric/side/state
markers.  A review receipt is evidence of a declared review, not proof of taste,
screenplay understanding or image quality.  Legacy cue contracts remain separate.
"""
from __future__ import annotations

from decimal import Decimal
import hashlib
import json
import re
import unicodedata


SCHEMA = 'PromptFidelityReviewV1'
_NUMERALS = {'零': 0, '〇': 0, '一': 1, '二': 2, '两': 2, '三': 3, '四': 4,
             '五': 5, '六': 6, '七': 7, '八': 8, '九': 9}
_OBJECTS = r'项链|木簪|皇冠|耳钉|耳饰|首饰|戒指|胸针|头纱|手套|帽子|发夹|腰带|饰品|妆面|底妆|妆'


def _ensure(condition, message):
    if not condition:
        raise ValueError(message)


def content_hash(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
                                    separators=(',', ':')).encode('utf-8')).hexdigest()


def _leaves(value, path):
    if isinstance(value, str) and value.strip():
        yield path, value
    elif isinstance(value, dict):
        for key, child in value.items():
            yield from _leaves(child, f'{path}.{key}')
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from _leaves(child, f'{path}.{index}')


_METADATA = {'basis', 'reason', 'rationale', 'evidence_status', 'source_refs', 'script_refs',
             'basis_refs', 'evidence_refs', 'test_status', 'status', 'mode', 'notes',
             'confidence', 'scope', 'schema_version', 'field', 'activation_reason'}


def _visible_leaves(value, path):
    """Traverse selected structural containers, omitting their evidence metadata."""
    if isinstance(value, str) and value.strip():
        yield path, value
    elif isinstance(value, dict):
        for name, child in value.items():
            if name not in _METADATA:
                yield from _visible_leaves(child, f'{path}.{name}')
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from _visible_leaves(child, f'{path}.{index}')


def design_inventory(design, stage):
    """Enumerate selected design, never a package-authored list of what to keep.

    Avatar/expression exclude body/clothing domains which are outside that frame.
    Everything else selected in the frame is required, including quiet details.
    No package can exempt a small visible part by labelling it low priority.
    """
    data = design.get('data', design)
    payload = data.get('payload', data)
    _ensure(isinstance(payload, dict), 'Fidelity source needs a design payload')
    inventory = {}
    contract = payload.get('prompt_detail_contract', {})
    if contract.get('stage') == stage:
        for item in contract.get('items', []):
            for field, cue in item.get('cues', {}).items():
                _ensure(isinstance(cue, str) and cue.strip(), 'Selected cue cannot be empty')
                detail_id = f'prompt_detail_contract.{item["id"]}.{field}'
                _ensure(detail_id not in inventory, 'Duplicate selected detail ID')
                inventory[detail_id] = cue
    covered = '\n'.join(inventory.values())
    for domain, details in payload.get('visual_details', {}).items():
        if stage in {'avatar', 'expression'} and domain in {'body', 'costume'}:
            continue
        for path, value in _visible_leaves(details, f'visual_details.{domain}'):
            if stage in {'avatar', 'expression'} and path.startswith('visual_details.adornments.body_hands'):
                continue
            if value not in covered:
                inventory[path] = value
    for key in ('morphology_details', 'identity_invariants'):
        value = payload.get(key, {})
        if key == 'morphology_details' and stage in {'avatar', 'expression'} and isinstance(value, dict):
            value = {k: v for k, v in value.items() if k == 'identity'}
        for path, text in _visible_leaves(value, key):
            if text not in covered:
                inventory[path] = text
    if stage in {'full_body', 'execution', 'costume_design'}:
        form = payload.get('body_form', {})
        anchors = form.get('proportion_anchors', {})
        for name, anchor in anchors.items():
            if isinstance(anchor, dict) and isinstance(anchor.get('relation'), str):
                inventory[f'body_form.proportion_anchors.{name}.relation'] = anchor['relation']
                for path, value in _visible_leaves(anchor.get('reference_points', []),
                                                  f'body_form.proportion_anchors.{name}.reference_points'):
                    inventory[path] = value
        for name in ('measurement_frame', 'proportions', 'masses', 'views'):
            for path, value in _visible_leaves(form.get(name, {}), f'body_form.{name}'):
                inventory[path] = value
        # The selected neutral posture and mobility constraints remain meaningful;
        # a narrative action used to test them is not a request to depict that event.
        for name in ('stance', 'mobility_result'):
            for path, value in _visible_leaves(form.get('action_check', {}).get(name, {}),
                                             f'body_form.action_check.{name}'):
                inventory[path] = value
    for name in ('appearance', 'facial_surface', 'execution_layout'):
        value = payload.get(name, {})
        if name == 'appearance' and stage in {'avatar', 'expression'} and isinstance(value, dict):
            value = {key: child for key, child in value.items() if key not in {'body', 'costume', 'clothing'}}
        for path, text in _visible_leaves(value, name):
            if text not in covered:
                inventory[path] = text
    if stage in {'execution', 'costume_design', 'full_body'}:
        for path, text in _visible_leaves(payload.get('costume', {}), 'costume'):
            inventory[path] = text
        direction = payload.get('costume_direction', {})
        for name in ('front_structure', 'back_structure', 'cut_and_fastening', 'layering',
                     'color_placement', 'material_behavior', 'recognition_focus',
                     'mobility_and_camera', 'state_continuity', 'makeup_and_hair',
                     'state_makeup', 'state_hair', 'head_ear_neck', 'wearable_accessories'):
            for path, text in _visible_leaves(direction.get(name, {}), f'costume_direction.{name}'):
                inventory[path] = text
    if stage in {'execution', 'costume_design'}:
        needs = payload.get('costume_direction', {}).get('scene_needs', {}).get('requirements', {})
        for name, need in needs.items():
            if need.get('decision') == 'design':
                for index, cue in enumerate(need.get('prompt_cues', [])):
                    inventory[f'costume_direction.scene_needs.{name}.{index}'] = cue
        if payload.get('schema_version') in {'GroupEnsembleDesignV1', 'SpeakingExtraDesignV1'}:
            for name in ('members', 'shared_visual_grammar', 'arrangement', 'world_style_translation',
                         'body_and_posture', 'face_and_hair', 'costume_front', 'costume_back',
                         'color_and_material', 'prop_and_action'):
                for path, text in _visible_leaves(payload.get(name, {}), name):
                    if not path.endswith('.slot'):
                        inventory[path] = text
            if type(payload.get('member_count')) is int:
                inventory['member_count'] = str(payload['member_count']) + '人'
    _ensure(inventory, 'Frozen source has no selected drawable details for this stage')
    return inventory


def _chinese_number(value):
    if '点' in value:
        left, right = value.split('点', 1)
        return _chinese_number(left) + '.' + ''.join(str(_NUMERALS[x]) for x in right)
    if '百' in value:
        left, right = value.split('百', 1)
        return str(int(_chinese_number(left or '一')) * 100 + int(_chinese_number(right.lstrip('零') or '零')))
    if '十' in value:
        left, right = value.split('十', 1)
        return str(int(_chinese_number(left or '一')) * 10 + int(_chinese_number(right or '零')))
    return ''.join(str(_NUMERALS[x]) for x in value)


def _normal(text):
    text = unicodedata.normalize('NFKC', text)
    # Only explicit quantities/measurements, not arbitrary characters inside words.
    pattern = r'[零〇一二两三四五六七八九十百]+(?:点[零〇一二两三四五六七八九]+)?(?=\s*(?:片|枚|只|件|个|层|道|组|头身|倍|厘米|毫米|度|颗|粒|扣))'
    text = re.sub(pattern, lambda m: _chinese_number(m.group()), text)
    return re.sub(r'\s+', '', text)


def hard_markers(text):
    """Extract only markers that code can compare without claiming comprehension."""
    text = _normal(text)
    numbers = {str(Decimal(x).normalize()) for x in re.findall(r'\d+(?:\.\d+)?', text)}
    quantities = set(re.findall(r'(\d+(?:\.\d+)?)(片|枚|只|件|个|层|道|组|头身|倍|厘米|毫米|度|颗|粒|扣)', text))
    quantities = {(str(Decimal(number).normalize()), unit) for number, unit in quantities}
    sides = set(re.findall(r'([左右])(?:侧|边)?(前发|侧发|发片|前片|后片|衣片|分缝|耳|眉|眼|肩|胸|袖|腰|手|腿|膝|腕|颈|鞋|脚|鬓)', text))
    states = set()
    for clause in re.split(r'[。；，,\n]', text):
        for match in re.finditer(_OBJECTS, clause):
            before, after = clause[:match.start()], clause[match.end():]
            absent = bool(re.search(r'(?:不戴|未戴|未佩戴|不佩戴|不再佩戴|不加|未添加|不添加|不使用|不施加|未施加|不穿|无|没有|留空|取下|摘下|移除)(?:任何|全部|所有|可卸)?$', before)
                          or re.match(r'(?:已|已经)?(?:取下|摘下|移除|留空|卸除|摘掉)', after))
            present = bool(re.search(r'(?:佩戴|戴着|戴有|配戴|穿着|穿戴|装有|带有|保留|\d+(?:枚|件|个|只))$', before))
            # Mentioning an object does not establish its state. Unrecognised
            # prose belongs to the controller's semantic check, never a guessed
            # positive which could reject a valid negative paraphrase.
            if absent or present:
                states.add(('absent' if absent else 'present', match.group()))
    return {'numbers': numbers, 'quantities': quantities, 'sides': sides, 'states': states}


def literal_retained(source, body):
    """An exact phrase under an obvious removal instruction is not coverage."""
    for match in re.finditer(re.escape(source), body):
        before = body[max(0, match.start() - 18):match.start()]
        if not re.search(r'(?:不要|避免|不采用|不保留|不使用|去掉|省略|不是|删除|不再是)\s*$', before):
            return True
    return False


def check_hard_markers(source, span, detail_id):
    _ensure(source not in span or literal_retained(source, span),
            f'Fidelity {detail_id} negates the selected source detail')
    expected, actual = hard_markers(source), hard_markers(span)
    for kind in ('numbers', 'quantities', 'sides'):
        _ensure(expected[kind] <= actual[kind],
                f'Fidelity {detail_id} changed or dropped hard {kind}: {sorted(expected[kind] - actual[kind])}')
    for state, obj in expected['states']:
        opposite = ('present' if state == 'absent' else 'absent', obj)
        _ensure(opposite not in actual['states'], f'Fidelity {detail_id} contradicts selected state: {obj}')


def validate_fidelity(package, inventory, source_sha256):
    """Validate a recorded controller review and objective guardrails only."""
    review = package.get('fidelity_review')
    _ensure(isinstance(review, dict) and review.get('schema_version') == SCHEMA,
            'New source-bound prompts need PromptFidelityReviewV1')
    _ensure(review.get('source_sha256') == source_sha256, 'Fidelity review design version changed')
    _ensure(review.get('prompt_sha256') == content_hash(package.get('prompts')), 'Fidelity review prompt content changed')
    semantic = review.get('semantic_review')
    _ensure(isinstance(semantic, dict) and semantic.get('reviewer') == 'controller' and
            semantic.get('verdict') == 'pass' and semantic.get('unresolved') == [],
            'Prompt needs a completed controller semantic review, not a code-only pass')
    _ensure(isinstance(semantic.get('notes'), str) and semantic['notes'].strip(),
            'Controller review must record its actual design and task findings')
    prompts = package.get('prompts')
    _ensure(isinstance(prompts, list) and prompts, 'Prompt fidelity needs actual prompts')
    bodies = {}
    for prompt in prompts:
        _ensure(isinstance(prompt, dict) and isinstance(prompt.get('id'), str) and prompt['id'].strip() and
                isinstance(prompt.get('text'), str) and prompt['text'].strip(), 'Prompt needs id and full text')
        _ensure(prompt['id'] not in bodies, 'Prompt IDs must be unique')
        bodies[prompt['id']] = prompt['text']
    coverage = review.get('coverage')
    _ensure(isinstance(coverage, list), 'Fidelity review needs source-to-body coverage')
    expected = {(prompt_id, detail_id) for prompt_id in bodies for detail_id in inventory}
    # Mechanical identity is stronger evidence than asking the model to repeat
    # the same span in another receipt. Only edited/nonliteral details need an
    # authored mapping; every selected source detail still belongs to expected.
    seen = {(prompt_id, detail_id) for prompt_id, body in bodies.items()
            for detail_id, source_text in inventory.items() if literal_retained(source_text, body)}
    literal_count = len(seen)
    explicit_seen = set()
    for row in coverage:
        _ensure(isinstance(row, dict), 'Fidelity coverage row must be an object')
        pair = row.get('prompt_id'), row.get('detail_id')
        _ensure(pair in expected and pair not in explicit_seen, 'Fidelity coverage has unknown or duplicate detail mapping')
        span = row.get('span')
        _ensure(isinstance(span, str) and span.strip() and span in bodies[pair[0]],
                f'Fidelity {pair[1]} must point to an actual prompt text span')
        check_hard_markers(inventory[pair[1]], span, pair[1])
        seen.add(pair)
        explicit_seen.add(pair)
    _ensure(seen == expected, f'Prompt dropped selected visible design details: {sorted(expected - seen)}')
    return {'verification_scope': 'source-inventory-and-hard-markers-with-recorded-controller-review',
            'literal_detail_matches': literal_count, 'explicit_review_mappings': len(explicit_seen),
            'semantic_equivalence_proven_by_code': False, 'image_review_performed': False}

files.scripts/prompt_canvas.py:
"""Check an actual task's parsed canvas ratio, with a deliberately narrow fallback.

This module does not parse general requirements, negatives or conflicting
choices. The controller supplies aspect_ratio for those cases. Bare body ratios
are never candidates. Defaults apply only when there is no current constraint.
"""
from __future__ import annotations

import math
import re
import unicodedata


_RATIO = r'[1-9][0-9]*\s*:\s*[1-9][0-9]*(?![\d.:])'
_LABEL = r'(?:画幅(?:比例|宽高比)?|画布(?:比例|宽高比)?|aspect\s+ratio)'
_AFFIRM = r'(?:必须|采用|设为|设置为|使用|改为|改成|调整为|保持|固定|要求|为|是|用|must\s+be|should\s+be|is|use|set\s+to|[:,=])'
_NEGATIVE_PREFIX = re.compile(r'(?:不要|不能|不准|不是|并非|避免|别|不要求|不强制|不考虑|\bnot|\bnever|\bavoid)\s*(?:使用|采用|设为|设置为|用|use|adopt|set\s+to)?\s*$', re.I)
_CANDIDATE = re.compile(_LABEL + r'\s*(?:(?:' + _AFFIRM + r'|不要|不能|不准|不使用|不采用|不设为|不是|并非|not|must\s+not\s+be)\s*)*(' + _RATIO + r')', re.I)
_POSITIVE = re.compile(_LABEL + r'\s*(?:' + _AFFIRM + r'\s*)*(' + _RATIO + r')', re.I)
_CHOICE = re.compile(r'\s*(?:或|还是|/|、|和|与|及|or|and)\s*(' + _RATIO + r')', re.I)


def _ensure(condition, message):
    if not condition:
        raise ValueError(message)


def _normal(text):
    return unicodedata.normalize('NFKC', text)


def canonical_ratio(value):
    _ensure(isinstance(value, str) and re.fullmatch(_RATIO, _normal(value).strip()),
            'Task aspect_ratio must be one positive integer width:height ratio')
    width, height = (int(part.strip()) for part in _normal(value).split(':'))
    factor = math.gcd(width, height)
    return f'{width // factor}:{height // factor}'


def explicit_canvas_ratio(request):
    """Recognise only labelled, single-target, affirmative canvas statements.

    A labelled negative or a multi-target choice needs controller resolution.
    This returns no assertion for arbitrary N:M strings or body measurements.
    """
    if not isinstance(request, str):
        return {'status': 'absent'}
    found, unresolved = set(), False
    for clause in re.split(r'[。；;！!\n，,]', _normal(request)):
        for match in _CANDIDATE.finditer(clause):
            positive = _POSITIVE.match(clause, match.start())
            if not positive or _NEGATIVE_PREFIX.search(clause[:match.start()]):
                unresolved = True
                continue
            found.add(canonical_ratio(positive.group(1)))
            position = positive.end()
            while choice := _CHOICE.match(clause, position):
                found.add(canonical_ratio(choice.group(1)))
                position = choice.end()
    if unresolved or len(found) > 1:
        return {'status': 'needs_resolution'}
    if found:
        return {'status': 'explicit', 'aspect_ratio': next(iter(found))}
    return {'status': 'absent'}


def _actual_constraint(inputs):
    parsed = explicit_canvas_ratio(inputs.get('request'))
    if 'aspect_ratio' in inputs:
        ratio = canonical_ratio(inputs['aspect_ratio'])
        _ensure(parsed['status'] != 'explicit' or parsed['aspect_ratio'] == ratio,
                'Parsed task aspect_ratio contradicts the explicit canvas request')
        return {'aspect_ratio': ratio, 'source': 'task.aspect_ratio'}
    _ensure(parsed['status'] != 'needs_resolution',
            'Canvas request needs controller-resolved task aspect_ratio; negative or conflicting choices are not parsed')
    if parsed['status'] == 'explicit':
        return {'aspect_ratio': parsed['aspect_ratio'], 'source': 'explicit_canvas_request'}
    return None


def resolve_canvas(inputs, stage, design_inputs=None, use_default=True):
    """The current actual task wins; source framing fills gaps, then defaults."""
    current = _actual_constraint(inputs)
    if current:
        return current
    if design_inputs is not None:
        frozen = _actual_constraint(design_inputs)
        if frozen:
            return {**frozen, 'source': 'frozen_design.' + frozen['source']}
    if use_default:
        return {'aspect_ratio': '3:4' if stage in {'avatar', 'expression'} else '9:16',
                'source': 'stage_default'}
    return None


def rendered_canvas_ratios(text):
    """Find declared canvas notation, excluding incidental body N:M values."""
    text = _normal(text)
    parsed = explicit_canvas_ratio(text)
    _ensure(parsed['status'] != 'needs_resolution', 'Prompt canvas declaration is negative or conflicting')
    ratios = {parsed['aspect_ratio']} if parsed['status'] == 'explicit' else set()
    # Existing prompts also use N:M竖版 / N:M画幅 or start a paragraph with
    # N:M 单人头像. Those are presentation notation, not a ratio deep in prose.
    for match in re.finditer(r'(' + _RATIO + r')\s*(?=画幅|画布|正方形|方形|竖版|横版)', text):
        ratios.add(canonical_ratio(match.group(1)))
    for match in re.finditer(r'^\s*(' + _RATIO + r')(?=\s|[。；,，;]|$)', text):
        tail = text[match.end():].lstrip()
        if not re.match(r'(?:头身|肩髋|肩宽|髋宽|肢段|上下肢|body|shoulder|hip|head)', tail, re.I):
            ratios.add(canonical_ratio(match.group(1)))
    return ratios


def validate_canvas_text(text, constraint):
    _ensure(isinstance(text, str) and text.strip(), 'Prompt needs its full canvas text')
    actual = rendered_canvas_ratios(text)
    expected = constraint['aspect_ratio']
    _ensure(actual == {expected},
            f'Prompt canvas must be {expected} from {constraint["source"]}; found {sorted(actual)}')


def validate_canvas_package(package, constraint):
    _ensure(canonical_ratio(package.get('aspect_ratio')) == constraint['aspect_ratio'],
            f'Prompt aspect_ratio must be {constraint["aspect_ratio"]} from {constraint["source"]}')
    prompts = package.get('prompts')
    _ensure(isinstance(prompts, list) and prompts, 'Candidate needs complete prompts')
    for prompt in prompts:
        _ensure(isinstance(prompt, dict), 'Prompt must be an object')
        validate_canvas_text(prompt.get('text'), constraint)

files.scripts/prompt_layout.py:
"""Check explicit prompt layout instructions, never the resulting picture.

The text remains the authority: booleans and an execution_layout object cannot
stand in for the actual crop, panel and clothing instructions. These deliberately
bounded checks catch omitted/contradictory geometry; the controller still checks
the meaning of the prompt. 生成后交付用户人工反馈，不自动审图；显式请求图像审查时才看图。
"""
from __future__ import annotations

import re
import unicodedata

from prompt_canvas import canonical_ratio, resolve_canvas, validate_canvas_text


STAGES = {'avatar', 'expression', 'full_body', 'execution'}
_NEG = re.compile(r'(?:不|无|勿|避免|禁止|不得|不能|不要|not|never|without)\s*[^。；;!?！\n]{0,7}$', re.I)
_QUADRANTS = re.compile(r'(左上|上左|右上|上右|左下|下左|右下|下右)(?:格|角|区域)?\s*[:：]?')
_ALIASES = {'上左': '左上', '上右': '右上', '下左': '左下', '下右': '右下'}


def _normal(text):
    return unicodedata.normalize('NFKC', text).replace('×', 'x').replace('°', '度')


def _has(text, pattern):
    """Require an affirmative occurrence, excluding nearby explicit negation."""
    for match in re.finditer(pattern, text, re.I):
        prefix = re.split(r'[。；;!?！\n，,]', text[:match.start()])[-1]
        # These are positive garment/crop terms, not a negation of the next noun.
        prefix = re.sub(r'无头|无袖|无图案|不含头部', '', prefix)
        if not _NEG.search(prefix):
            return True
    return False


def _panels(text):
    found = {}
    matches = list(_QUADRANTS.finditer(text))
    for index, match in enumerate(matches):
        key = _ALIASES.get(match.group(1), match.group(1))
        end = matches[index + 1].start() if index + 1 < len(matches) else len(text)
        # The layout paragraph ends before unrelated clothing prose. Otherwise
        # e.g. a small shoulder reveal becomes a claim about back-panel scale.
        paragraph = re.search(r'\n\s*\n', text[match.end():end])
        if paragraph:
            end = match.end() + paragraph.start()
        found.setdefault(key, []).append(text[match.end():end])
    return {key: '。'.join(values) for key, values in found.items()}


def _fraction(text, region):
    label = (r'上(?:方[^。；;\n]{0,5}(?:区|格)|面两格|区|排|部)'
             if region == 'upper' else r'下(?:方[^。；;\n]{0,5}(?:区|格)|面两格|区|排|部)')
    fraction = r'(?:1\s*/\s*3|三分之一|33(?:\.\d+)?\s*%)' if region == 'upper' else r'(?:2\s*/\s*3|三分之二|6[67](?:\.\d+)?\s*%)'
    return _has(text, label + r'[^。；;\n]{0,32}' + fraction)


def _execution(text):
    # Boots and shoes share a visible footwear endpoint. Do not require users
    # to replace correct garment nouns merely to satisfy literal keywords.
    text = text.replace('靴', '鞋')
    errors = []
    if not _has(text, r'2\s*[xX*]\s*2|两行两列|二行二列'):
        errors.append('execution: 正文须明确2×2两行两列，不能只声明四格')
    if not _fraction(text, 'upper') or not _fraction(text, 'lower'):
        errors.append('execution: 正文须明确上区约占总高1/3、下区约占总高2/3')
    if _has(text, r'上下(?:两区|两排|区域)?(?:各半|等高|均分)|(?:等大|等高|均等)(?:的)?四格|上(?:区|排)[^。；;\n]{0,20}(?:1/2|二分之一|50\s*%)'):
        errors.append('execution: 上下各半或等高四格与标准1/3、2/3版式矛盾')
    panels = _panels(text)
    for key in ('左上', '右上', '左下', '右下'):
        if key not in panels:
            errors.append(f'execution: 正文缺少{key}格的实际内容和裁切')
    upper_left, upper_right = panels.get('左上', ''), panels.get('右上', '')
    if not (_has(upper_left, r'正面') and _has(upper_left, r'头像|面孔|脸部|面部|头肩')):
        errors.append('execution: 左上须为正面头像，不能用全身或半侧脸替代')
    if not (_has(upper_right, r'45\s*度|四十五度') and _has(upper_right, r'头像|面孔|脸部|面部|头肩')):
        errors.append('execution: 右上须为约45°半侧面头像')
    for key, value in (('左上', upper_left), ('右上', upper_right)):
        if _has(value, r'全身|从头到鞋|90\s*度|九十度'):
            errors.append(f'execution: {key}格有与脸部格不符的全身或90°侧面指令')
    front = panels.get('左下', '')
    if not (_has(front, r'正面') and _has(front, r'服装|衣装|衣服')):
        errors.append('execution: 左下须展示正面服装主体')
    if not _has(front, r'放大|更近|近景|占满|满格|更满'):
        errors.append('execution: 左下须明确放大、更近的服装展示尺度')
    no_head = (_has(front, r'(?:头部|头脸|整颗头)[^。；;\n]{0,8}(?:完全|彻底)[^。；;\n]{0,5}(?:出画|不入画)')
               or _has(front, r'无头(?:的|放大)?正面|不含头部|头部完全不入画')
               or _has(front, r'头发[、，,与和及\s]*(?:下巴[、，,与和及\s]*嘴唇|嘴唇[、，,与和及\s]*下巴)[^。；;\n]{0,5}(?:全部|完全|彻底)出画'))
    if not no_head:
        errors.append('execution: 左下须明确头部彻底出画；metadata或“服装格”不能代替裁切正文')
    if not (_has(front, r'颈肩以下|颈部以下|肩颈以下|脖子以下|颈肩下方') and _has(front, r'鞋')):
        errors.append('execution: 左下范围须从颈肩以下到鞋，不能截在腰或腿中部')
    for label, pattern in (('肩', r'肩'), ('双臂', r'双臂|两臂|两条手臂|左右手臂'),
                           ('双手', r'双手|两手|两只手'), ('躯干', r'躯干|胸腰|上身'),
                           ('腿', r'双腿|两腿|腿部|腿'), ('鞋', r'鞋')):
        if not _has(front, pattern):
            errors.append(f'execution: 左下正文缺少完整{label}的可见要求')
    if not _has(front, r'完整|全部入画|均入画|全入画'):
        errors.append('execution: 左下须明确肩臂手躯干腿鞋完整入画')
    if _has(front, r'(?:头部|头顶|嘴唇|下巴|头发)[^。；;\n]{0,4}(?:入画|可见|露出|残留)|(?:裁至|裁到|只到|截止在?)(?:腰|膝|大腿|腿中部)|含头全身|带头全身'):
        errors.append('execution: 左下存在露头、嘴唇/下巴/头发残留或截断下肢的矛盾指令')
    back = panels.get('右下', '')
    if not (_has(back, r'背面|背视') and _has(back, r'完整|全身') and _has(back, r'头部|头顶|后脑|从头') and _has(back, r'鞋')):
        errors.append('execution: 右下须明确完整背面，从头部/后脑到鞋全部入画')
    if _has(back, r'无头|不含头|裁掉(?:头|鞋)|只到(?:腰|膝|大腿)|小(?:幅|尺寸)(?:的)?(?:背面|人物|全身)|小人物|缩小(?:人物|全身)'):
        errors.append('execution: 右下不能裁头、裁鞋或缩成过小的背面人物')
    return errors


def _attire(text, stage, inputs):
    exception = inputs.get('attire_exception')
    if isinstance(exception, dict) and exception.get('description') and exception.get('basis'):
        return [] if exception['description'] in text else ['模卡着装例外须在正文完整写出实际方案']
    if stage in {'avatar', 'expression'}:
        if _has(text, r'(?:服装|衣服|衣着)(?:完全)?不入画|仅露面部|只露面部'):
            return []
        if _has(text, r'白色[^。；;\n]{0,8}(?:运动)?背心|白(?:色)?(?:无图案|纯色)?(?:运动)?背心'):
            return []
        return ['头像/表情正文须明确服装不入画或白色模卡背心，不用metadata代替着装']
    if stage == 'full_body':
        if not (_has(text, r'白色[^。；;\n]{0,8}(?:运动)?背心|白(?:色)?(?:无图案|纯色)?(?:运动)?背心') and _has(text, r'短裤') and _has(text, r'赤脚|光脚')):
            return ['full_body: 人形模卡正文须有白色背心、短裤和赤脚，定制遮盖方案须有真实例外依据']
    return []


def _body_proportions(text):
    errors = []
    number = r'(?:\d+(?:\.\d+)?|[一二三四五六七八九十]+)'
    if not re.search(number + r'\s*(?:头身|个?头高)|(?:头高|头长)[^。；;\n]{0,16}(?:全高|身高)[^。；;\n]{0,12}' + number + r'|(?:全高|身高)[^。；;\n]{0,16}' + number + r'[^。；;\n]{0,8}(?:头高|头长)', text):
        errors.append('full_body: 正文须给头高与全高的明确比例端点')
    if not re.search(r'(?:肩峰|肩宽)[^。；;\n]{0,24}(?:骨盆|髋宽|髋部)[^。；;\n]{0,16}' + number, text):
        errors.append('full_body: 正文须给肩峰/肩宽与骨盆/髋宽的明确比例')
    if not re.search(r'(?:上段|上身|躯干)[^。；;\n]{0,35}(?:下段|下身|腿长|下肢)[^。；;\n]{0,20}' + number, text):
        errors.append('full_body: 正文须写同一测量体系的上段/下段比例，不能只有“长腿”')
    upper = re.search(r'(?:上段|上身|躯干)[^。；;\n]{0,5}(?:从|起于)?[^。；;\n，,]{1,15}(?:至|到|—|–)[^。；;\n，,]{1,15}', text)
    lower = re.search(r'(?:下段|下身|腿长|下肢)[^。；;\n]{0,5}(?:从|起于)?[^。；;\n，,]{1,15}(?:至|到|—|–)[^。；;\n，,]{1,15}', text)
    if not (upper and lower):
        errors.append('full_body: 上段和下段须分别写实际测量起止点，不能只写上下身数值比')
    return errors


def validate_entry(entry, inputs, morphology='human', asset_mode='individual'):
    """Return explicit-text contract errors; an empty list is not visual approval."""
    errors = []
    if not isinstance(entry, dict) or not isinstance(inputs, dict):
        return ['Prompt entry and actual inputs must be objects']
    stage, raw = entry.get('stage'), entry.get('text')
    if stage not in STAGES:
        return ['Prompt document stage must be avatar/expression/full_body/execution']
    if not isinstance(raw, str) or not raw.strip():
        return ['Prompt entry needs its actual complete text']
    text = _normal(raw)
    ensemble = asset_mode == 'ensemble'
    if asset_mode in {'ensemble', 'speaking_extra'} and stage != 'execution':
        errors.append('群演/群像仅需execution，不强套头像、表情、模卡四图链')
    try:
        if ensemble and not any(k in inputs for k in ('aspect_ratio',)):
            # Group count determines a suitable canvas; never guess it from body ratios.
            constraint = resolve_canvas(inputs, stage, use_default=False)
            if constraint is None:
                constraint = {'aspect_ratio': canonical_ratio(entry.get('aspect_ratio')), 'source': 'ensemble presentation'}
        else:
            constraint = resolve_canvas(inputs, stage)
        if 'aspect_ratio' in entry and canonical_ratio(entry['aspect_ratio']) != constraint['aspect_ratio']:
            errors.append('Prompt entry aspect_ratio differs from the actual task canvas')
        validate_canvas_text(raw, constraint)
    except ValueError as exc:
        errors.append(str(exc))
    human = morphology in {'human', 'humanoid'}
    if ensemble:
        if not (_has(text, r'同一(?:张)?画布|同画布|同一画面') and _has(text, r'完整全身|全身完整|从头到脚') and _has(text, r'从左到右|自左至右|左至右')):
            errors.append('ensemble: 正文须有同画布完整全身群像与从左到右槽位')
        if _has(text, r'2\s*[xX*]\s*2|无头正面'):
            errors.append('ensemble: 不采用独立人物四格或无头裁切')
        return errors
    if not human:
        if stage == 'execution' and not (_has(text, r'替代布局|多视图|多角度|2\s*[xX*]\s*2') and _has(text, r'轮廓|形态|结构') and _has(text, r'尺度|比例|大小')):
            errors.append('nonhuman: 正文须写适应该形态的替代视图、结构与尺度，不强套人脸/无头服装')
        return errors
    if stage in {'avatar', 'expression'}:
        errors.extend(_attire(text, stage, inputs))
        if not (_has(text, r'完整头部|头部完整|完整头顶|头顶[^。；;\n]{0,8}(?:完整|入画)') and _has(text, r'双肩|两肩')):
            errors.append('头像/表情正文须给完整头部和双肩的头肩取景')
    if stage == 'expression':
        sixteen = inputs.get('expression_grid') == 16
        wanted = r'4\s*[xX*]\s*4|十六格|16格' if sixteen else r'3\s*[xX*]\s*3|九宫格|9格'
        if not _has(text, wanted):
            errors.append('expression: 正文须明确3×3九宫格；16格只接受实际输入明确选择')
        if not (_has(text, r'从左到右|自左至右|从上到下|逐行|顺序') and _has(text, r'标签|标注|标明|文字')):
            errors.append('expression: 正文须说明表情格顺序与中文标签')
    elif stage == 'full_body':
        errors.extend(_attire(text, stage, inputs))
        errors.extend(_body_proportions(text))
        if not (_has(text, r'头(?:顶|部)?[^。；;\n]{0,12}(?:双脚|脚底|脚|足)') and _has(text, r'双手|两手') and _has(text, r'完整|全部入画|均入画')):
            errors.append('full_body: 正文须明确头到双脚及双手完整入画')
        if _has(text, r'无头正面|头部彻底出画|头部完全出画'):
            errors.append('full_body: 单独模卡必须含头，不能沿用执行图左下裁切')
    elif stage == 'execution':
        errors.extend(_execution(text))
    return errors


def validate_package(package, inputs=None, morphology='human', asset_mode='individual'):
    """Guard new formal submissions/generation; do not recheck historic approvals."""
    actual = dict(inputs or {})
    # Formal callers must derive morphology/mode from the real design/project.
    errors = []
    for item in package.get('prompts', []):
        entry = {'stage': package.get('stage'), 'text': item.get('text'),
                 'aspect_ratio': package.get('aspect_ratio')}
        errors.extend(validate_entry(entry, actual, morphology, asset_mode))
    if not package.get('prompts'):
        errors.append('Prompt package needs actual prompts[].text')
    return list(dict.fromkeys(errors))
